{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate, a small polar molecule with an ionizable acid and amide, has an absolute oral bioavailability of 11 ± 1% in humans, directly supporting a low F (<20%) for the similarly polar, ionizable query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Colistin, a cyclic peptide, has negligible oral bioavailability, indicating that peptide-like polar structures can have very low oral F; transferability is limited by size but the direction is consistent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Octreotide, a cyclic peptide, has oral bioavailability of about 0.3% in healthy volunteers, reinforcing poor oral absorption for peptide-like polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Monomethyl fumarate/MMF has 90-95% oral bioavailability, but as a small lipophilic ester it is not representative of the query's multiple ionizable carboxylates and amides.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Biotin has 100% oral bioavailability, but this is achieved through active transport and is unlikely to transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "ALZ-801 has ~52% oral bioavailability, but as an amino acid-sulfonate prodrug it likely relies on transporter-mediated absorption, not applicable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar cyclic dipeptide (diketopiperazine) bearing two free carboxylates and multiple amide groups, predicting poor passive permeability. The most mechanistically relevant evidence, acamprosate (F ~11%), a small ionizable acid/amide molecule, and several cyclic peptide analogues with very low oral F, support F <20%. High-F comparators such as biotin, MMF, and ALZ-801 depend on active transport or low polarity and are poorly transferable.",
  "evidence_gaps": [
    "No high-similarity analogue with a diketopiperazine core and two carboxylate side chains.",
    "No direct permeability or transporter data for the query.",
    "Uncertainty about possible active uptake or prodrug behavior.",
    "Conflicting/ambiguous records for arginine and MMF limit their interpretability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

